/**
 * Heritage API - 非遗项目接口
 * 
 * 接口列表:
 * - getHeritages: 获取所有非遗项目 (支持筛选)
 * - getHeritageDetail: 获取单个非遗项目详情
 * - getCategories: 获取非遗分类
 * - getRegions: 获取所有地区
 * - search: 全局搜索
 */

import request from './request.js'

export default {
  /**
   * 获取所有非遗项目
   * @param {object} params - 查询参数 { category, region, level, search, page, limit }
   */
  getHeritages(params = {}) {
    return request.get('/heritage', { params })
  },

  /**
   * 获取单个非遗项目详情
   * @param {string} id - 项目ID
   */
  getHeritageDetail(id) {
    return request.get(`/heritage/${id}`)
  },

  /**
   * 获取非遗分类列表
   */
  getCategories() {
    return request.get('/heritage/categories')
  },

  /**
   * 获取所有地区
   */
  getRegions() {
    return request.get('/heritage/regions')
  },

  /**
   * 全局搜索
   * @param {object} params - 搜索参数 { q, type }
   */
  search(params = {}) {
    return request.get('/search', { params })
  }
}
